// The LITIUS Blind: the custom dimension, the Llave de Raices and the island generation.
// Generated by tools/litius_blind.py (the islands are built by gen.js).
import { BlockPermutation, BlockVolume, ItemStack, system, world } from "@minecraft/server";
import { buildCell, cellOf, CELL, HALF, MARGIN, SPAWN } from "./gen.js";

const CFG = {"dimension": "litius:the_litius_blind", "key": "litius:llave_de_raices", "radius": 2, "opsPerStep": 48};
const DIM = CFG.dimension;

// ------------------------------------------------------------ the dimension
system.beforeEvents.startup.subscribe((ev) => {
  ev.dimensionRegistry.registerCustomDimension(DIM);
});

function litius() {
  return world.getDimension(DIM);
}

function seed() {
  let s = world.getDynamicProperty("litius:seed");
  if (typeof s !== "number") {
    s = Math.floor(Math.random() * 2147483647);
    world.setDynamicProperty("litius:seed", s);
  }
  return s;
}

// ------------------------------------------------------------ generation
// The dimension is generated one cell (4x4 chunks) at a time, around the players.
const perms = new Map();
function perm(block) {
  const id = typeof block === "string" ? block : block.id;
  const key = typeof block === "string" ? block : `${id}|${JSON.stringify(block.states)}`;
  if (!perms.has(key)) {
    let p = null;
    try {
      p = BlockPermutation.resolve(id, typeof block === "string" ? undefined : block.states);
    } catch {
      try {
        p = BlockPermutation.resolve(id);
      } catch {
        console.warn(`[LITIUS] bloque desconocido: ${key}`);
      }
    }
    perms.set(key, p);
  }
  return perms.get(key);
}

function apply(dim, op) {
  if (op[0] === "f") {
    const [, x1, y1, z1, x2, y2, z2, b] = op;
    const p = perm(b);
    if (!p) return;
    if (x1 === x2 && y1 === y2 && z1 === z2) dim.getBlock({ x: x1, y: y1, z: z1 })?.setPermutation(p);
    else dim.fillBlocks(new BlockVolume({ x: x1, y: y1, z: z1 }, { x: x2, y: y2, z: z2 }), p);
    return;
  }
  const [, x, y, z, b, items] = op;
  const p = perm(b);
  if (!p) return;
  const block = dim.getBlock({ x, y, z });
  if (!block) return;
  block.setPermutation(p);
  if (op[0] === "c") {
    const inv = block.getComponent("minecraft:inventory")?.container;
    if (!inv) return;
    for (const [id, count] of items) {
      try {
        inv.addItem(new ItemStack(id, count));
      } catch {}
    }
  }
}

function* applyAll(dim, ops, done) {
  let n = 0;
  for (const op of ops) {
    try {
      apply(dim, op);
    } catch {}
    if (++n % CFG.opsPerStep === 0) yield;
  }
  done();
}

const cellKey = (cx, cz) => `litius:cell:${cx}:${cz}`;
const isBuilt = (cx, cz) => world.getDynamicProperty(cellKey(cx, cz)) === true;
const building = new Map(); // key -> promise
const retryAt = new Map(); // key -> tick: cells that could not be loaded wait a little

function areaId(cx, cz, what) {
  return `litius_${what}_${cx}_${cz}`.replace(/-/g, "m");
}

async function loadArea(dim, id, from, to) {
  try {
    await world.tickingAreaManager.createTickingArea(id, { dimension: dim, from, to });
    return true;
  } catch (e) {
    console.warn(`[LITIUS] no se pudo crear la zona de carga ${id}: ${e}`);
    return false;
  }
}

function dropArea(id) {
  try {
    world.tickingAreaManager.removeTickingArea(id);
  } catch {}
}

function generateCell(cx, cz) {
  const key = cellKey(cx, cz);
  if (isBuilt(cx, cz)) return Promise.resolve(true);
  if (building.has(key)) return building.get(key);
  const job = (async () => {
    const dim = litius();
    const x0 = cx * CELL - HALF - MARGIN, x1 = cx * CELL + HALF - 1 + MARGIN;
    const z0 = cz * CELL - HALF - MARGIN, z1 = cz * CELL + HALF - 1 + MARGIN;
    const id = areaId(cx, cz, "gen");
    const loaded = await loadArea(dim, id, { x: x0, y: 0, z: z0 }, { x: x1, y: 0, z: z1 });
    // without a ticking area, only build when the players already keep the whole cell loaded
    if (!loaded && (!dim.getBlock({ x: x0, y: 64, z: z0 }) || !dim.getBlock({ x: x1, y: 64, z: z1 }))) {
      retryAt.set(key, system.currentTick + 200);
      return false;
    }
    const { ops } = buildCell(cx, cz, seed());
    await new Promise((resolve) => system.runJob(applyAll(dim, ops, resolve)));
    world.setDynamicProperty(key, true);
    if (loaded) dropArea(id);
    return true;
  })();
  building.set(key, job);
  job.catch((e) => console.warn(`[LITIUS] error generando ${cx},${cz}: ${e}`)).finally(() => building.delete(key));
  return job;
}

// Queue: the cells around the players in the dimension, nearest first, one at a time.
let busy = false;
system.runInterval(() => {
  if (busy) return;
  let best = null;
  for (const player of world.getPlayers()) {
    if (player.dimension.id !== DIM) continue;
    const pcx = cellOf(player.location.x), pcz = cellOf(player.location.z);
    for (let dx = -CFG.radius; dx <= CFG.radius; dx++)
      for (let dz = -CFG.radius; dz <= CFG.radius; dz++) {
        const cx = pcx + dx, cz = pcz + dz;
        if (isBuilt(cx, cz) || (retryAt.get(cellKey(cx, cz)) ?? 0) > system.currentTick) continue;
        const d = dx * dx + dz * dz;
        if (!best || d < best.d) best = { cx, cz, d };
      }
  }
  if (!best) return;
  busy = true;
  generateCell(best.cx, best.cz).finally(() => (busy = false));
}, 20);

// ------------------------------------------------------------ no mobs (for now)
const KEEP = new Set(["minecraft:player", "minecraft:armor_stand"]);
function isMob(entity) {
  return !KEEP.has(entity.typeId) && entity.getComponent("minecraft:health") !== undefined;
}

world.afterEvents.entitySpawn.subscribe(({ entity }) => {
  try {
    if (entity.dimension.id === DIM && isMob(entity)) entity.remove();
  } catch {}
});

system.runInterval(() => {
  try {
    for (const e of litius().getEntities({ excludeTypes: ["minecraft:player"] })) if (isMob(e)) e.remove();
  } catch {}
}, 100);

// ------------------------------------------------------------ the Llave de Raices
const traveling = new Set();

async function teleportLoaded(player, dim, loc, id) {
  const ok = await loadArea(dim, id, { x: loc.x - 4, y: 0, z: loc.z - 4 }, { x: loc.x + 4, y: 0, z: loc.z + 4 });
  player.teleport(loc, { dimension: dim });
  if (ok) system.runTimeout(() => dropArea(id), 100);
}

async function enter(player) {
  const here = player.location;
  player.setDynamicProperty("litius:back", JSON.stringify({
    dim: player.dimension.id, x: here.x, y: here.y, z: here.z,
  }));
  player.onScreenDisplay.setActionBar("§2Las raíces se abren...");
  await generateCell(0, 0);
  await teleportLoaded(player, litius(), SPAWN, areaId(player.id, 0, "in"));
  player.onScreenDisplay.setTitle("§2The LITIUS Blind", { subtitle: "§7islas sobre el vacío", fadeInDuration: 10, stayDuration: 50, fadeOutDuration: 20 });
  player.playSound("portal.travel", { volume: 0.4 });
}

async function leave(player) {
  let back = null;
  try {
    back = JSON.parse(player.getDynamicProperty("litius:back") ?? "null");
  } catch {}
  if (!back || back.dim === DIM) {
    const spawn = world.getDefaultSpawnLocation();
    const dim = world.getDimension("minecraft:overworld");
    const id = areaId(player.id, 0, "out");
    const loc = { x: spawn.x + 0.5, y: 0, z: spawn.z + 0.5 };
    const ok = await loadArea(dim, id, { x: loc.x - 4, y: 0, z: loc.z - 4 }, { x: loc.x + 4, y: 0, z: loc.z + 4 });
    const top = dim.getTopmostBlock({ x: loc.x, z: loc.z });
    loc.y = top ? top.y + 1 : 100;
    player.teleport(loc, { dimension: dim });
    if (ok) system.runTimeout(() => dropArea(id), 100);
  } else {
    await teleportLoaded(player, world.getDimension(back.dim), { x: back.x, y: back.y, z: back.z }, areaId(player.id, 0, "out"));
  }
  player.playSound("portal.travel", { volume: 0.4 });
}

world.afterEvents.itemUse.subscribe(({ source: player, itemStack }) => {
  if (itemStack?.typeId !== CFG.key || player?.typeId !== "minecraft:player") return;
  if (traveling.has(player.id)) return;
  traveling.add(player.id);
  const go = player.dimension.id === DIM ? leave(player) : enter(player);
  go.catch((e) => console.warn(`[LITIUS] viaje fallido: ${e}`)).finally(() => traveling.delete(player.id));
});
